locals_and_loops:
waza collatz(start: int64) -> int64 {
    kaku value = start; kaku steps = 0;
    aida (value != 1) {
        moshi (value - (value / 2) * 2 == 0) { value = value / 2; } sore { value = value * 3 + 1; }
        steps = steps + 1;
    }
    kaesu steps;
}
