kata Point { x: int64; y: int64; name: string; }
sentaku Shape { Circle(int64); Rect(int64, int64); Empty; }
waza area(s: Shape) -> int64 {
    awase (s) {
        baai Circle(r) { kaesu r * r * 3; }
        baai Rect(w, h) { kaesu w * h; }
        baai Empty { kaesu 0; }
    }
    kaesu -1;
}
